#include "stock_native_projectile_wire.hpp"
#include "stock_native_bot_python.hpp"
using namespace stock_native_projectile;
namespace p=stock_native_bot_python;
PyObject* parse(PyObject*,PyObject* raw){Launch l;if(!readLaunch(raw,l)){if(PyErr_Occurred())return nullptr;Py_RETURN_NONE;}try{auto out=p::dict();p::set(out.get(),"id",p::text(l.id));p::set(out.get(),"shooter",p::integer(l.shooter));p::set(out.get(),"signature",p::text(l.source_signature));p::set(out.get(),"damage",p::number(l.shot.shell.damage));p::set(out.get(),"device_damage",p::number(l.shot.device_damage_mean.value_or(-1)));p::set(out.get(),"radius",p::number(l.shot.explosion_radius));p::set(out.get(),"segment",p::integer(l.segment));return out.release();}catch(...){return nullptr;}}
PyObject* packed(PyObject*,PyObject*){Dispatch d;d.serial=13;d.epoch=7;d.kind="resolve";Proposal v;v.frontier.projectile="x";v.outcome="impact";v.impact={1,2,3};v.hit_vehicle=true;damage::Effect e;e.target={false,4};e.damage=10;e.result=2;e.impact=v.impact;e.hull_damage=11;e.critical_target_base_revision=15;e.critical_target_ack_sequence=9;damage::CriticalOutcome c;c.device_loss["engineHealth"]=12.34567;c.device_loss["gunHealth"]=.0004;c.crew_operations.insert("loader1");c.ignite=true;c.state.crew_ko.insert("loader1");e.critical=c;e.crew_roster={"commander","driver","loader1","gunner1"};v.direct=e;d.proposal=v;return packDispatches({d});}
PyMethodDef methods[]={{"parse",parse,METH_O,nullptr},{"packed",packed,METH_NOARGS,nullptr},{nullptr,nullptr,0,nullptr}};
PyMODINIT_FUNC initprojectile_wire_test(){Py_InitModule("projectile_wire_test",methods);}
